"""Standalone user-facing per-scene analysis dashboard; hypotheses remain labeled."""
import base64
import html
import json
from pathlib import Path
import subprocess


def export(output='results/halisaha-analiz-v051.html'):
    from schematic_heatmap import export as export_heatmaps
    export_heatmaps()
    records=[];panels=[]
    roots=sorted(p for p in Path('results/full_analysis').glob('scene_*') if p.is_dir())
    def image(path):return 'data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode()
    labels={'shot_candidate':'Şut adayı','transfer_candidate':'Kontrol değişimi / pas adayı','goal_entry_candidate':'Kale bölgesine giriş adayı','endline_crossing':'Aut çizgisi geçiş adayı'}
    for i,root in enumerate(roots):
        s=json.loads((root/'summary.json').read_text());events=json.loads((root/'events.json').read_text());movement=json.loads((root/'movement.json').read_text())
        web=root/'web.mp4'
        if not web.exists() or web.stat().st_mtime < (root/'analysis.mp4').stat().st_mtime: subprocess.run(['ffmpeg','-y','-loglevel','error','-i',str(root/'analysis.mp4'),'-c:v','libx264','-pix_fmt','yuv420p','-movflags','+faststart','-an',str(web)],check=True)
        heat_audit=json.loads((root/'schematic_heatmap.json').read_text())
        video='data:video/mp4;base64,'+base64.b64encode(web.read_bytes()).decode()
        cards=''.join(f'<div class="metric"><strong>{s["event_candidates"].get(k,0)}</strong><span>{v}</span></div>' for k,v in labels.items())
        timeline=''.join(f'<a class="seek" href="#video-{i}" data-time="{e["time_s"]}">{e["time_s"]:.2f} s · {labels[e["type"]]}</a>' for e in events) or '<p>Bu koşullarla olay adayı üretilmedi. Kesitte olay olmadığı anlamına gelmez.</p>'
        table=''.join(f'<tr><td>P{r["track_id"]}</td><td>{r["observation_s"]:.2f} s</td><td>{r["movement_px"]:.1f} px</td></tr>' for r in sorted(movement,key=lambda x:-x['observation_s'])[:15])
        ownership=' · '.join(f'{ {"unknown":"Belirsiz","player":"Oyuncu kontrolü adayı","free_ball":"Serbest top adayı","contested":"Mücadele adayı"}[k]}: {v:.2f} s' for k,v in s['ownership_seconds'].items())
        panels.append(f'''<section id="scene-{i}" data-index="{i}"><div class="heading"><h2>Kesit {i+1}</h2><span>{s['duration_s']:.1f} saniye · {s['frames']} kare</span></div><div class="columns"><div><video id="video-{i}" controls playsinline preload="none" src="{video}"></video><p class="legend">Yeşil: kişi · sarı: top adayı · turkuaz çember: seçilmiş top adayı · turuncu: kale adayı · mor: aut çizgisi adayı</p><nav class="tabs"><a href="#heat-{i}">Isı haritasına git</a><a href="#scene-{(i+1)%len(roots)}">Sonraki kesit →</a><a href="#contents">Tüm kesitler</a></nav><h3 id="heat-{i}">Şematik saha üzerinde yoğunluk</h3><img class="heatmap" alt="Kesit {i+1}: yapay saha üzerinde göreli yoğunluk haritası" src="{image(root/'schematic_heatmap.png')}"><p>45 × 25 m örnek çizim. Yalnız görünen alan şemaya normalize edildi; gerçek tam-saha konumlandırması veya metre kalibrasyonu değildir. {heat_audit['mapped_observations']} / {heat_audit['input_observations']} kişi gözlemi haritaya aktarıldı; kalanlar dönüşüm alanı dışında.</p><details><summary>Saha çizgilerini ve dönüşüm alanını göster</summary><img class="geometry" alt="Kaynak görüntüde kullanılan dönüşüm alanı" src="{image(root/'heatmap_projection.png')}"></details><p>Saha: {'aday sınır bulundu' if s['pitch_detected'] else 'bulunamadı'} · {s['marking_segments']} çizgi parçası · {s['goal_candidates']} kale adayı · {s['endline_candidates']} aut çizgisi adayı. Saha otomatik; kale/aut bölgeleri bu pilot görüntülerde AI görsel incelemesiyle yaklaşık düzeltildi. İnsan doğrulaması ve metre kalibrasyonu yok.</p></div><aside><h3>Kesit ölçümleri</h3><div class="metrics"><div class="metric"><strong>%{s['ball_coverage_percent']:.1f}</strong><span>Seçilmiş top adayı kapsamı</span></div><div class="metric"><strong>{s.get('person_suppressed',0)}</strong><span>Kişi kutusunda kaldırılan aday</span></div>{cards}</div><p class="note">Olay sayıları otomatik adaydır. Onaylı pas, şut ve gol toplamları henüz bilinmiyor. Sıfır aday, sıfır gerçek olay değildir.</p><h3>Top kontrolü</h3><p>{ownership}</p><h3>Olayları görüntüde incele</h3>{timeline}</aside></div><details><summary>Oyuncu hareketi ve ölçüm sınırları</summary><table><tr><th>Geçici ID</th><th>Gözlenen süre</th><th>Görüntü hareketi</th></tr>{table}</table><p>Hareket, yalnız ardışık karelerde gözlenen ayak noktalarının piksel farkıdır. Kutuların titremesi ve ID değişimi etkiler. Metre, hız, oyuncu reytingi veya gerçek koşu mesafesi değildir. Isı haritası kişi gözlemlerinin normalize edilmiş yoğunluğudur; renkler her kesitte kendi en yoğun bölgesine göre ölçeklenir; kesitler arasında toplam hareket karşılaştırması yapılmaz. Şema üzerindeki yön, kamera yönüne bağlıdır; gerçek hücum yönü belirlenmemiştir. Kaleler duvar/korkulukla karışabilir; 2B bölgeye giriş golü kanıtlamaz. Oyuncu kutusuna giren gerçek top da isteğiniz doğrultusunda kaldırılır.</p></details></section>''')
        records.append(dict(summary=s,events=events,movement=movement,heatmap=heat_audit))
    navigation=''.join(f'<a href="#scene-{i}">Kesit {i+1}</a>' for i in range(len(records)))
    script="""for(const section of document.querySelectorAll('section')){for(const link of section.querySelectorAll('.seek'))link.addEventListener('click',()=>{const video=section.querySelector('video'),time=Number(link.dataset.time);if(video.readyState>=1)video.currentTime=time;else{video.addEventListener('loadedmetadata',()=>{video.currentTime=time},{once:true});video.load()}})}"""
    Path(output).write_text('''<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Halı Saha · Analiz</title><style>*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:#0c1720;color:#e8f2f5;font:16px system-ui}header{padding:24px;background:#122c39}h1{margin:0 0 8px}main{max-width:1400px;margin:auto;padding:18px}.columns{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(280px,1fr);gap:24px}aside,details{background:#182e3a;padding:18px;border-radius:12px}.heading,.tabs{display:flex;gap:16px;align-items:center;flex-wrap:wrap}video,img{width:100%;border-radius:10px}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:10px}.metric{background:#234452;border-radius:10px;padding:14px}.metric strong{display:block;font-size:26px}.metric span,.legend{font-size:13px;color:#bcd1da}.note{background:#594720;padding:12px;border-radius:8px}a{color:#9bdcff}section{scroll-margin-top:12px;border-top:1px solid #456;margin-top:24px;padding-top:14px}.scene-nav{display:flex;flex-wrap:wrap;gap:8px}.scene-nav a,.tabs a,.seek{display:inline-block;text-decoration:none;background:#245364;padding:12px;border-radius:6px;min-height:44px}h3{scroll-margin-top:12px}button,select{background:#245364;color:#fff;border:1px solid #5792a5;padding:12px;border-radius:6px;font:inherit;cursor:pointer}p{line-height:1.5}.seek{display:block;margin:8px 0}table{width:100%;max-width:650px;text-align:left}td,th{padding:8px}details{margin-top:20px}@media(max-width:850px){.columns{grid-template-columns:1fr}main{padding:10px}header{padding:16px}}</style><header><h1>Halı Saha Analiz</h1><div>Otomatik analiz prototipi · insan onayı bekleyen sonuçlar</div></header><main><nav id="contents" class="scene-nav" aria-label="Kesitler">'''+navigation+'</nav><p>Tüm kesitler bu sayfada. Bağlantıyla veya aşağı kaydırarak inceleyebilirsin; ısı haritaları doğrudan görünür.</p>'+''.join(panels)+'<footer><p>Şablon ölçü kaynakları: <a href="https://nurteks.com.tr/haberler/blog/hali-saha-yapimi-ve-hali-saha-olculeri-hakkinda-her-sey">Nurteks halı saha ölçüleri</a> · <a href="https://www.thefa.com/football-rules-governance/lawsandrules/laws/football-5-5/law-1---the-playing-area">FA küçük saha kuralları</a>. Kaynaklardaki ölçüler videodaki sahaların ölçüldüğünü göstermez.</p></footer></main><script>'+script+'</script></html>',encoding='utf-8')
    Path(output).with_suffix('.json').write_text(json.dumps(records,indent=2))


if __name__=='__main__':export()
